from pathlib import Path

FILES = {'src/az_enterprise/core/project_model_alpha301.py': '"""ATLAS ZERO Alpha 3.0.1 — minimal Unified Project Model."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import asdict, dataclass, field, replace\nfrom datetime import datetime, timezone\nfrom enum import Enum\nimport json\nfrom typing import Any, Mapping\nfrom uuid import uuid4\n\n\ndef new_id(prefix: str) -> str:\n    return f"{prefix}_{uuid4().hex}"\n\n\ndef utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\nclass ProjectStatus(str, Enum):\n    DRAFT = "DRAFT"\n    IN_PROGRESS = "IN_PROGRESS"\n    REVIEW = "REVIEW"\n    APPROVED = "APPROVED"\n    PUBLISHED = "PUBLISHED"\n    ARCHIVED = "ARCHIVED"\n\n\nclass SceneStatus(str, Enum):\n    DRAFT = "DRAFT"\n    READY = "READY"\n    REWORK = "REWORK"\n    APPROVED = "APPROVED"\n\n\nclass ExperienceStatus(str, Enum):\n    OBSERVED = "OBSERVED"\n    VALIDATED = "VALIDATED"\n    REJECTED = "REJECTED"\n    PROMOTED = "PROMOTED"\n\n\n@dataclass(frozen=True)\nclass Asset:\n    id: str\n    kind: str\n    uri: str\n    metadata: Mapping[str, Any] = field(default_factory=dict)\n\n    def __post_init__(self) -> None:\n        if not self.id or not self.kind or not self.uri:\n            raise ValueError("asset id, kind and uri are required")\n\n\n@dataclass(frozen=True)\nclass Scene:\n    id: str\n    title: str\n    order: int\n    duration_seconds: float\n    narration: str = ""\n    status: SceneStatus = SceneStatus.DRAFT\n    asset_ids: tuple[str, ...] = ()\n    metadata: Mapping[str, Any] = field(default_factory=dict)\n\n    def __post_init__(self) -> None:\n        if not self.id or not self.title:\n            raise ValueError("scene id and title are required")\n        if self.order < 0:\n            raise ValueError("scene order cannot be negative")\n        if self.duration_seconds < 0:\n            raise ValueError("scene duration cannot be negative")\n\n\n@dataclass(frozen=True)\nclass Task:\n    id: str\n    target: str\n    description: str\n    completed: bool = False\n\n    def __post_init__(self) -> None:\n        if not self.id or not self.target or not self.description:\n            raise ValueError("task id, target and description are required")\n\n\n@dataclass(frozen=True)\nclass Experience:\n    id: str\n    observation: str\n    confidence: float\n    source_project_ids: tuple[str, ...]\n    status: ExperienceStatus = ExperienceStatus.OBSERVED\n    evidence: Mapping[str, Any] = field(default_factory=dict)\n\n    def __post_init__(self) -> None:\n        if not self.id or not self.observation:\n            raise ValueError("experience id and observation are required")\n        if not 0.0 <= self.confidence <= 1.0:\n            raise ValueError("experience confidence must be between 0 and 1")\n        if not self.source_project_ids:\n            raise ValueError("experience requires source projects")\n\n\n@dataclass(frozen=True)\nclass Project:\n    id: str\n    title: str\n    version: int = 1\n    status: ProjectStatus = ProjectStatus.DRAFT\n    scenes: tuple[Scene, ...] = ()\n    assets: tuple[Asset, ...] = ()\n    tasks: tuple[Task, ...] = ()\n    experiences: tuple[Experience, ...] = ()\n    metadata: Mapping[str, Any] = field(default_factory=dict)\n    created_at: str = field(default_factory=utc_now)\n    updated_at: str = field(default_factory=utc_now)\n\n    def __post_init__(self) -> None:\n        if not self.id or not self.title:\n            raise ValueError("project id and title are required")\n        if self.version < 1:\n            raise ValueError("project version must be at least 1")\n        self.validate()\n\n    def validate(self) -> None:\n        self._ensure_unique("scene", [item.id for item in self.scenes])\n        self._ensure_unique("asset", [item.id for item in self.assets])\n        self._ensure_unique("task", [item.id for item in self.tasks])\n        self._ensure_unique(\n            "experience", [item.id for item in self.experiences]\n        )\n\n        asset_ids = {asset.id for asset in self.assets}\n        missing = {\n            asset_id\n            for scene in self.scenes\n            for asset_id in scene.asset_ids\n            if asset_id not in asset_ids\n        }\n        if missing:\n            raise ValueError(\n                "scenes reference missing assets: " + ", ".join(sorted(missing))\n            )\n\n        orders = [scene.order for scene in self.scenes]\n        if len(orders) != len(set(orders)):\n            raise ValueError("scene order values must be unique")\n\n    @staticmethod\n    def _ensure_unique(label: str, values: list[str]) -> None:\n        if len(values) != len(set(values)):\n            raise ValueError(f"duplicate {label} ids are not allowed")\n\n    def evolve(self, **changes: Any) -> "Project":\n        changes.setdefault("version", self.version + 1)\n        changes.setdefault("updated_at", utc_now())\n        return replace(self, **changes)\n\n    def add_scene(self, scene: Scene) -> "Project":\n        return self.evolve(scenes=self.scenes + (scene,))\n\n    def add_asset(self, asset: Asset) -> "Project":\n        return self.evolve(assets=self.assets + (asset,))\n\n    def add_task(self, task: Task) -> "Project":\n        return self.evolve(tasks=self.tasks + (task,))\n\n    def add_experience(self, experience: Experience) -> "Project":\n        return self.evolve(experiences=self.experiences + (experience,))\n\n    def to_dict(self) -> dict[str, Any]:\n        data = asdict(self)\n        data["status"] = self.status.value\n        for scene in data["scenes"]:\n            scene["status"] = scene["status"].value\n        for experience in data["experiences"]:\n            experience["status"] = experience["status"].value\n        return data\n\n    def to_json(self) -> str:\n        return json.dumps(self.to_dict(), ensure_ascii=False, sort_keys=True)\n\n    @classmethod\n    def from_dict(cls, data: Mapping[str, Any]) -> "Project":\n        return cls(\n            id=str(data["id"]),\n            title=str(data["title"]),\n            version=int(data.get("version", 1)),\n            status=ProjectStatus(data.get("status", ProjectStatus.DRAFT.value)),\n            scenes=tuple(\n                Scene(\n                    **{\n                        **scene,\n                        "status": SceneStatus(\n                            scene.get("status", SceneStatus.DRAFT.value)\n                        ),\n                        "asset_ids": tuple(scene.get("asset_ids", ())),\n                    }\n                )\n                for scene in data.get("scenes", ())\n            ),\n            assets=tuple(Asset(**asset) for asset in data.get("assets", ())),\n            tasks=tuple(Task(**task) for task in data.get("tasks", ())),\n            experiences=tuple(\n                Experience(\n                    **{\n                        **experience,\n                        "status": ExperienceStatus(\n                            experience.get(\n                                "status", ExperienceStatus.OBSERVED.value\n                            )\n                        ),\n                        "source_project_ids": tuple(\n                            experience.get("source_project_ids", ())\n                        ),\n                    }\n                )\n                for experience in data.get("experiences", ())\n            ),\n            metadata=data.get("metadata", {}),\n            created_at=str(data.get("created_at", utc_now())),\n            updated_at=str(data.get("updated_at", utc_now())),\n        )\n\n    @classmethod\n    def from_json(cls, payload: str) -> "Project":\n        return cls.from_dict(json.loads(payload))\n', 'tests/test_project_model_alpha301.py': 'from __future__ import annotations\n\nimport pytest\n\nfrom az_enterprise.core.project_model_alpha301 import (\n    Asset,\n    Experience,\n    Project,\n    ProjectStatus,\n    Scene,\n    SceneStatus,\n    Task,\n)\n\n\ndef make_project() -> Project:\n    return Project(id="project_1", title="Hogueras Test")\n\n\ndef test_project_starts_at_version_one():\n    project = make_project()\n\n    assert project.version == 1\n    assert project.status is ProjectStatus.DRAFT\n\n\ndef test_add_asset_creates_new_version():\n    project = make_project()\n    updated = project.add_asset(\n        Asset(id="asset_1", kind="video", uri="file://clip.mp4")\n    )\n\n    assert project.assets == ()\n    assert updated.version == 2\n    assert len(updated.assets) == 1\n\n\ndef test_add_scene_with_existing_asset():\n    project = make_project().add_asset(\n        Asset(id="asset_1", kind="video", uri="file://clip.mp4")\n    )\n    updated = project.add_scene(\n        Scene(\n            id="scene_1",\n            title="Opening",\n            order=0,\n            duration_seconds=5.0,\n            status=SceneStatus.READY,\n            asset_ids=("asset_1",),\n        )\n    )\n\n    assert updated.version == 3\n    assert updated.scenes[0].asset_ids == ("asset_1",)\n\n\ndef test_missing_scene_asset_is_rejected():\n    with pytest.raises(ValueError, match="missing assets"):\n        Project(\n            id="project_1",\n            title="Broken",\n            scenes=(\n                Scene(\n                    id="scene_1",\n                    title="Opening",\n                    order=0,\n                    duration_seconds=5.0,\n                    asset_ids=("missing",),\n                ),\n            ),\n        )\n\n\ndef test_duplicate_scene_order_is_rejected():\n    with pytest.raises(ValueError, match="order"):\n        Project(\n            id="project_1",\n            title="Broken",\n            scenes=(\n                Scene("scene_1", "A", 0, 1.0),\n                Scene("scene_2", "B", 0, 1.0),\n            ),\n        )\n\n\ndef test_task_can_be_added():\n    project = make_project().add_task(\n        Task(id="task_1", target="visual", description="Replace clip")\n    )\n\n    assert project.tasks[0].target == "visual"\n\n\ndef test_experience_requires_valid_confidence():\n    with pytest.raises(ValueError, match="confidence"):\n        Experience(\n            id="exp_1",\n            observation="Retention improved",\n            confidence=1.2,\n            source_project_ids=("project_1",),\n        )\n\n\ndef test_json_round_trip():\n    project = (\n        make_project()\n        .add_asset(Asset("asset_1", "video", "file://clip.mp4"))\n        .add_scene(Scene("scene_1", "Opening", 0, 5.0, asset_ids=("asset_1",)))\n        .add_experience(\n            Experience(\n                id="exp_1",\n                observation="Fast opening improved retention",\n                confidence=0.8,\n                source_project_ids=("project_1",),\n            )\n        )\n    )\n\n    restored = Project.from_json(project.to_json())\n\n    assert restored == project\n', 'docs/architecture/alpha_301_project_model.md': '# ATLAS ZERO Alpha 3.0.1 — Minimal Unified Project Model\n\nThis version introduces one immutable project object as a future source of\ntruth without changing the existing Runtime or Director components.\n\nIncluded entities:\n\n- `Project`\n- `Scene`\n- `Asset`\n- `Task`\n- `Experience`\n\nPrinciples:\n\n- immutable state;\n- every change creates a new project version;\n- scene assets must exist in the project;\n- identifiers and scene order must be unique;\n- experiences are recorded but do not modify policy;\n- JSON round-trip is supported.\n\nDeliberately excluded:\n\n- scene graph;\n- knowledge engine;\n- automatic learning;\n- Runtime integration;\n- Director integration;\n- persistence layer.\n\nThese are deferred until the existing Hogueras test flow remains stable.\n'}

def main():
    root = Path.cwd()
    for relative_path, content in FILES.items():
        target = root / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            backup = target.with_suffix(target.suffix + ".bak")
            backup.write_text(target.read_text(encoding="utf-8"), encoding="utf-8")
            print(f"BACKUP  {backup}")
        target.write_text(content, encoding="utf-8")
        print(f"CREATED {target}")

    print("\nRun:")
    print("python -m pytest tests/test_project_model_alpha301.py -v")

if __name__ == "__main__":
    main()
